head.script:
scwin.chktree_onlabelclick = function(value, nodeElement, index) {};
scwin.chktree_ontoggleclick = function(nodeElement, index, isRendered) {};
scwin.treeview1_ondrop = function(dragNode, dropNode, dragControl, dropControl, e) {
    dragControl.appendNode(dropNode, dragNode);
    dragControl.removeNode(dragNode);
};
scwin.fireMouseHover = function(node) {
    if (document.createEventObject) {
        node.fireEvent('onmouseover');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('mouseover', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.onmouseover == 'function') {
        node.onmouseover();
    }
}
scwin.__triggerMouseover = function(id) {
    var el = WebSquare.wUnit.getDomById($p.id + id);
    scwin.fireMouseHover(el);
}
scwin.__isPointer = function() {
    return WebSquare.wUnit.getJq("#treeview1_icon_3").css("cursor") == "pointer";
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "3000");
    // Test step 1. 샘플파일 실행 후 treeview_icon_label에 마우스로 가져간다.
    //1. After running the sample file, mouse over treeview_icon_label.
    WebSquare.wUnit.addCommand("set", "scwin.__triggerMouseover('treeview1_icon_3')");
    WebSquare.wUnit.addCommand("pause", "100");
    // verify step 1. 손가락 모양으로 보여진다.(이전에는 손가락 모양이 아닌 포인터였음)
    //1. 손가락 모양으로 보여진다.(이전에는 손가락 모양이 아닌 포인터였음)
    WebSquare.wUnit.addCommand("assert", "scwin.__isPointer()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
